package cn.minidayz.patcher;
import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** Full signed inventory matching. Never infers native compatibility from version names. */
public final class ContentMatch {
 public static JSONObject inventory(File apk,FilesEx.Watch w)throws Exception{ZipFile z=new ZipFile(apk);JSONObject result=new JSONObject();try{Map<String,ZipEntry> entries=FilesEx.entries(z);int done=0;for(ZipEntry e:entries.values()){FilesEx.check(w);if(e.isDirectory()||FilesEx.signature(e.getName()))continue;JSONObject item=new JSONObject().put("size",e.getSize()).put("sha256",FilesEx.hex(FilesEx.digest(z.getInputStream(e),w)));if(e.getName().equals("AndroidManifest.xml")){try{item.put("identity",ManifestIdentity.hash(FilesEx.read(z.getInputStream(e),16777216)));}catch(Exception unsupported){if(w.cancelled())FilesEx.check(w);}}result.put(e.getName(),item);w.progress(++done,entries.size());}return result;}finally{z.close();}}
 public static JSONObject difference(JSONObject actual,JSONObject expected)throws Exception{JSONArray differences=new JSONArray();int count=0,changed=0,missing=0,extra=0;Set<String> names=new TreeSet<String>();Iterator<?> it=actual.keys();while(it.hasNext())names.add((String)it.next());it=expected.keys();while(it.hasNext())names.add((String)it.next());for(String n:names){JSONObject a=actual.optJSONObject(n),b=expected.optJSONObject(n);String kind=null;if(a==null){kind="missing";missing++;}else if(b==null){kind="extra";extra++;}else if(!a.getString("sha256").equals(b.getString("sha256"))||a.getLong("size")!=b.getLong("size")){if(n.equals("AndroidManifest.xml")&&a.has("identity")&&b.has("identity")&&a.getString("identity").equals(b.getString("identity")))continue;kind="changed";changed++;}if(kind!=null){count++;if(differences.length()<100)differences.put(new JSONObject().put("entry",n).put("kind",kind).put("actual",a==null?JSONObject.NULL:a).put("expected",b==null?JSONObject.NULL:b));}}return new JSONObject().put("count",count).put("changed",changed).put("missing",missing).put("extra",extra).put("entries",differences).put("truncated",count>differences.length());}
 public static final class Match {public JSONObject profile,analysis;public byte[] originalManifest;}
 public static Match find(File apk,File mod,JSONObject module,FilesEx.Watch w)throws Exception{w.stage("content-match","自动核对全部游戏文件，区分重新打包与实际更新");JSONObject actual=inventory(apk,w);JSONArray profiles=module.getJSONArray("profiles");Match found=new Match();int closest=Integer.MAX_VALUE;for(int i=0;i<profiles.length();i++){FilesEx.check(w);JSONObject p=profiles.getJSONObject(i),expected=p.optJSONObject("input_inventory");if(expected==null)continue;JSONObject diff=difference(actual,expected);int count=diff.getInt("count");if(count<closest){closest=count;found.analysis=new JSONObject().put("closest_profile",p.getString("id")).put("difference",diff);}if(count==0&&found.profile==null)found.profile=p;}
  if(found.profile!=null){JSONObject record=found.profile.getJSONObject("input_inventory").getJSONObject("AndroidManifest.xml");String path=found.profile.getString("input_manifest_payload");FilesEx.require(path.startsWith("payload/")&&FilesEx.safeName(path),"E_PAYLOAD_PATH");ZipFile z=new ZipFile(mod);try{ZipEntry e=z.getEntry(path);FilesEx.require(e!=null&&e.getSize()<=16777216,"E_PAYLOAD_MISSING");found.originalManifest=FilesEx.read(z.getInputStream(e),16777216);String hash=FilesEx.hex(java.security.MessageDigest.getInstance("SHA-256").digest(found.originalManifest));JSONObject blob=module.getJSONObject("payloads").getJSONObject(path);FilesEx.require(hash.equals(record.getString("sha256"))&&hash.equals(blob.getString("sha256"))&&found.originalManifest.length==record.getLong("size")&&found.originalManifest.length==blob.getLong("size"),"E_PAYLOAD_HASH: 原清单校验失败");FilesEx.require(ManifestIdentity.hash(found.originalManifest).equals(record.getString("identity")),"E_MANIFEST_IDENTITY");}finally{z.close();}}
  return found;
 }
}
